import { ChartLegendItem } from 'components/ChartLegend/ChartLegend';
import { LineBarChartColors } from 'pages/pillars/ValueCreation/PerformanceTool/hooks/useLineBarChartDatasets/useLineBarChartDatasets';
import dataFoundations from 'theme/colors/dataFoundations';

const { series } = dataFoundations.charts.bg;

export const COMMERCIAL_RESULTS_LINE_BAR_CHART_COLORS: LineBarChartColors = {
  lastYear: series.lastYear,
  current: series.current,
};

export const COMMERCIAL_RESULTS_LINE_BAR_CHART_LEGEND_STYLE: Pick<
  ChartLegendItem,
  'shape' | 'size'
> = {
  shape: 'rectangle',
  size: 'medium',
};
